/*
 * Builds every site icon from one piece of artwork: a coffee cup seen from
 * above, on a saucer, with the Bolt mark poured into the foam as latte art.
 *
 *   npm run icons
 *
 * Writes into public/: favicon.svg, favicon.ico (16/32/48), apple-touch-icon.png,
 * icon-192.png, icon-512.png and icon-maskable-512.png. Edit the artwork here,
 * never the generated files.
 */
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { Resvg } from "@resvg/resvg-js";

const PUBLIC = fileURLToPath(new URL("../public/", import.meta.url));

// Font Awesome 6 "bolt", the same mark as the navbar logo (viewBox 448 x 512).
const BOLT =
  "M349.4 44.6c5.9-13.7 1.5-29.7-10.6-38.5s-28.6-8-39.9 1.8l-256 224c-10 8.8-13.6 22.9-8.9 35.3S50.7 288 64 288H175.5L98.6 467.4c-5.9 13.7-1.5 29.7 10.6 38.5s28.6 8 39.9-1.8l256-224c10-8.8 13.6-22.9 8.9-35.3s-16.6-20.7-30-20.7H272.5L349.4 44.6z";

const COLORS = {
  tile: "#A6481F", // clay, the colour of every call to action on the site
  saucer: "#8F3D1A",
  saucerRing: "#9C4420",
  rim: "#FAF6EE",
  ceramic: "#E6D7BE",
  crema: ["#B57440", "#6A391D"],
  foam: "#F6EBD8",
};

const CUP = { cx: 29, cy: 32, r: 20, coffee: 16, bolt: 0.056 };

/** The cup and saucer, drawn on a 64 x 64 grid. */
function artwork() {
  const { cx, cy, r, coffee, bolt } = CUP;
  const bx = (cx - 224 * bolt).toFixed(3);
  const by = (cy - 256 * bolt).toFixed(3);
  return `
    <circle cx="32" cy="32" r="28" fill="${COLORS.saucer}"/>
    <circle cx="32" cy="32" r="24.5" fill="none" stroke="${COLORS.saucerRing}" stroke-width="1"/>
    <rect x="${cx + r - 4}" y="${cy - 4.75}" width="10.5" height="9.5" rx="4.75" fill="${COLORS.rim}"/>
    <circle cx="${cx}" cy="${cy}" r="${r}" fill="${COLORS.rim}"/>
    <circle cx="${cx}" cy="${cy}" r="${coffee + 1.2}" fill="${COLORS.ceramic}"/>
    <circle cx="${cx}" cy="${cy}" r="${coffee}" fill="url(#crema)"/>
    <path transform="translate(${bx} ${by}) scale(${bolt})" d="${BOLT}" fill="${COLORS.foam}"/>`;
}

/**
 * radius: corner rounding of the tile (0 for platforms that apply their own mask).
 * scale: shrinks the artwork towards the centre, for maskable icons' safe zone.
 */
function icon({ radius = 14, scale = 1 } = {}) {
  const art = scale === 1 ? artwork() : `<g transform="translate(32 32) scale(${scale}) translate(-32 -32)">${artwork()}</g>`;
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64">
  <!-- Generated by scripts/build-icons.js: edit the artwork there. -->
  <defs>
    <radialGradient id="crema" cx="0.4" cy="0.36" r="0.72">
      <stop offset="0" stop-color="${COLORS.crema[0]}"/>
      <stop offset="1" stop-color="${COLORS.crema[1]}"/>
    </radialGradient>
  </defs>
  <rect width="64" height="64" rx="${radius}" fill="${COLORS.tile}"/>${art}
</svg>
`;
}

function png(svg, size) {
  return new Resvg(svg, { fitTo: { mode: "width", value: size } }).render().asPng();
}

/** An .ico that simply wraps PNG images, which every current browser reads. */
function ico(images) {
  const header = Buffer.alloc(6);
  header.writeUInt16LE(0, 0);
  header.writeUInt16LE(1, 2);
  header.writeUInt16LE(images.length, 4);
  const entries = [];
  let offset = 6 + 16 * images.length;
  for (const { size, data } of images) {
    const entry = Buffer.alloc(16);
    entry.writeUInt8(size >= 256 ? 0 : size, 0);
    entry.writeUInt8(size >= 256 ? 0 : size, 1);
    entry.writeUInt16LE(1, 4); // colour planes
    entry.writeUInt16LE(32, 6); // bits per pixel
    entry.writeUInt32LE(data.length, 8);
    entry.writeUInt32LE(offset, 12);
    offset += data.length;
    entries.push(entry);
  }
  return Buffer.concat([header, ...entries, ...images.map((image) => image.data)]);
}

const rounded = icon();
const fullBleed = icon({ radius: 0 });
// Maskable icons may be cropped to a circle of 80% diameter; keep the saucer inside it.
const maskable = icon({ radius: 0, scale: 0.8 });

const outputs = {
  "favicon.svg": rounded,
  "favicon.ico": ico([16, 32, 48].map((size) => ({ size, data: png(rounded, size) }))),
  "apple-touch-icon.png": png(fullBleed, 180),
  "icon-192.png": png(rounded, 192),
  "icon-512.png": png(rounded, 512),
  "icon-maskable-512.png": png(maskable, 512),
};

for (const [name, data] of Object.entries(outputs)) {
  writeFileSync(PUBLIC + name, data);
  console.log(`public/${name}`);
}
